(() => {
  'use strict';
  const data=window.STUDY_CURRICULUM;
  const all=data.courses.flatMap(course=>course.weeks.flatMap(week=>week.readings.map(reading=>({course,week,reading}))));
  const missing=all.filter(x=>x.reading.status==='missing');
  const entries=new Map(), drafts=new Map(), sessionDraftIds=new Map();
  let ready=false, loading=true, loadError='';
  const states={assigned:'Assigned text',alternative:'Alternative edition',manuscript:'Author manuscript',reprint:'Teaching reprint',missing:'Not collected'};
  const progressNames={'not-started':'Not started','in-progress':'In progress',done:'Done'};
  const el=(tag,value,cls)=>{const n=document.createElement(tag);if(value)n.textContent=value;if(cls)n.className=cls;return n;};
  const a=(title,href,cls)=>{const n=el('a',title,cls);n.href=href;if(href.startsWith('https:')){n.target='_blank';n.rel='noopener noreferrer';}return n;};
  const button=(title,fn,cls)=>{const n=el('button',title,cls);n.type='button';n.addEventListener('click',fn);return n;};
  const route=(c,w)=>`#study-${c.id}-${w.number}`;
  const studyRoute=r=>`#session-${r.id}`;
  const defaults=()=>({progress:'not-started',notes:'',resume:'',chatUrl:''});
  const readingState=r=>entries.get('reading:'+r.id)?.data||defaults();
  let draftPrefix='',draftKey='',draftRecovered=false,draftWarning='';
  const recoveredCopies=new Map();
  function persistDrafts(){if(!draftKey)return;try{
    const dirty=[...drafts].filter(([,d])=>d.dirty);
    if(dirty.length)localStorage.setItem(draftKey,JSON.stringify({at:Date.now(),drafts:dirty,sessions:[...sessionDraftIds]}));else localStorage.removeItem(draftKey);
    for(const [key,raw]of recoveredCopies)if(localStorage.getItem(key)===raw)localStorage.removeItem(key);recoveredCopies.clear();
  }catch{draftWarning='This browser cannot keep unfinished edits. Save before leaving.';}}
  function restoreDrafts(scope){if(draftPrefix)return;draftPrefix='life:study-drafts:'+scope+':';draftKey=draftPrefix+crypto.randomUUID();try{
    const records=[];for(let n=0;n<localStorage.length;n++){const key=localStorage.key(n);if(key.startsWith(draftPrefix)){const raw=localStorage.getItem(key);try{records.push({key,raw,...JSON.parse(raw)});}catch{}}}
    records.sort((a,b)=>a.at-b.at);for(const record of records){for(const [id,d]of record.drafts||[]){if(!d?.dirty)continue;const saved=entries.get(id);if(saved&&JSON.stringify(saved.data)===JSON.stringify(d.data))continue;drafts.set(id,d);draftRecovered=true;}for(const [id,key]of record.sessions||[])if(drafts.has(key))sessionDraftIds.set(id,key);recoveredCopies.set(record.key,record.raw);}
    persistDrafts();
  }catch{draftWarning='Draft recovery is unavailable. Save before leaving.';}}
  const unsaved=()=>[...drafts.values()].some(d=>d.dirty);
  const refresh=()=>window.dispatchEvent(new Event('courseworkchange'));
  function draft(id,fallback){if(!drafts.has(id)){const e=entries.get(id);drafts.set(id,{data:structuredClone(e?.data||fallback),version:e?.version||0,dirty:false});}return drafts.get(id);}
  async function load(){loading=true;try{const response=await fetch('/api/coursework',{cache:'no-store'});if(!(response.headers.get('content-type')||'').includes('application/json'))throw Error('Saving is available after this version is published.');const result=await response.json();if(!response.ok)throw Error(result.error||'Could not load coursework.');entries.clear();result.entries.forEach(e=>entries.set(e.id,e));if(result.draftScope)restoreDrafts(result.draftScope);ready=true;loadError='';for(const [key,d] of drafts)if(!d.dirty)drafts.delete(key);}catch(e){loadError=e.message;ready=false;}finally{loading=false;refresh();}}
  async function save(id,value,version){if(!ready)throw Error(loadError||'Wait for your saved coursework to load, then retry.');const response=await fetch('/api/coursework/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({version,data:value})});const result=await response.json();if(!response.ok)throw Error(result.error||'Saving failed.');entries.set(id,result.entry);return result.entry;}
  function connection(parent){const box=el('div',null,'sync-state');box.setAttribute('role','status');if(loading)box.append(el('span','Loading your progress and notes…'));else if(!ready){box.append(el('span',loadError||'Your saved coursework is unavailable.'),button('Retry loading',()=>load()));}else box.append(el('span','Progress and notes loaded · saves sync across devices'));if(draftRecovered)box.append(el('span','Unfinished edits restored on this device.'));if(draftWarning)box.append(el('span',draftWarning));parent.append(box);}
  function count(c,w){const rows=w?w.readings:c.weeks.flatMap(x=>x.readings);return{done:rows.filter(r=>readingState(r).progress==='done').length,total:rows.length};}
  function progressControl(r,parent){const label=el('label',null,'progress-control');label.append(el('span','Your progress'));const select=el('select');select.setAttribute('aria-label',`Progress for ${r.title}`);for(const [value,title]of Object.entries(progressNames)){const option=el('option',title);option.value=value;select.append(option);}select.value=readingState(r).progress;select.disabled=!ready;const message=el('span',ready?'':(loading?'Loading…':'Not loaded'),'save-status');message.setAttribute('role','status');select.addEventListener('change',async()=>{select.disabled=true;message.textContent='Saving…';try{const id='reading:'+r.id;const record=await save(id,{...readingState(r),progress:select.value},entries.get(id)?.version||0);const d=drafts.get(id);if(d){d.version=record.version;d.data.progress=record.data.progress;}refresh();}catch(e){select.value=readingState(r).progress;message.textContent=e.message;}finally{select.disabled=!ready;}});label.append(select,message);parent.append(label);}
  function card({course,week,reading:r}){const item=el('section',null,'reading-card');const top=el('div',null,'reading-meta');top.append(el('span',r.kind),el('span',states[r.status],`reading-status ${r.status}`));item.append(top,el('h2',r.title),el('p',[r.author,r.scope].filter(Boolean).join(' · '),'reading-scope'));if(r.note){const detail=el('details',null,'edition-details');detail.append(el('summary',r.check?'Edition & reference question':'Edition details'),el('p',r.note,'edition-note'));item.append(detail);}const actions=el('div',null,'reading-actions');if(r.url)actions.append(a(readingState(r).progress==='in-progress'?'Continue studying':'Study this reading',studyRoute(r),'primary-action'),a('Open text',r.url));else actions.append(el('span','Reading still needed','missing-label'));item.append(actions);progressControl(r,item);return item;}
  function fieldsForm(id,fallback,fields,heading){const d=draft(id,fallback),form=el('form',null,'notes-form');if(heading)form.append(el('h3',heading));for(const field of fields){const label=el('label');label.append(el('span',field.title));const input=el(field.input?'input':'textarea');input.value=d.data[field.key]||'';input.setAttribute('data-draft-field',id+':'+field.key);input.maxLength=field.max||24000;if(field.input)input.type='url';else input.rows=field.rows||5;if(field.placeholder)input.placeholder=field.placeholder;input.addEventListener('input',()=>{d.data[field.key]=input.value;d.dirty=true;persistDrafts();message.textContent=draftWarning||'Draft kept on this device · not yet saved';});label.append(input);form.append(label);}const controls=el('div',null,'reading-actions');const submit=el('button','Save','primary-action');submit.type='submit';const message=el('span',d.dirty?'Unsaved changes':entries.has(id)?'Saved':'','save-status');message.setAttribute('role','status');controls.append(submit,message);form.append(controls);form.addEventListener('submit',async event=>{event.preventDefault();submit.disabled=true;message.textContent='Saving…';const value=structuredClone(d.data);try{const record=await save(id,value,d.version);d.version=record.version;if(JSON.stringify(value)===JSON.stringify(d.data))d.dirty=false;persistDrafts();message.textContent=d.dirty?'Saved earlier edit · newer changes unsaved':'Saved across devices';if(!d.dirty&&form.onSaved)form.onSaved(record);}catch(e){message.textContent=e.message;}finally{submit.disabled=false;}});return form;}
  function planForm(course){const id='plan:'+course.id;const value=entries.get(id)?.data||{week:1,chatUrl:''};const form=el('form',null,'plan-form');const label=el('label','Teaching week');const select=el('select');for(let n=1;n<=8;n++){const o=el('option','Week '+n);o.value=String(n);select.append(o);}select.value=String(value.week);select.disabled=!ready;label.append(select);const submit=el('button',entries.has(id)?'Update week':'Set week');submit.type='submit';submit.disabled=!ready;const message=el('span',null,'save-status');message.setAttribute('role','status');form.append(label,submit,message);form.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;try{await save(id,{...value,week:Number(select.value)},entries.get(id)?.version||0);refresh();}catch(error){message.textContent=error.message;submit.disabled=false;}});return form;}
  function home(text){setHeading('Coursework','Your week, your readings, your place to continue.','Life App · Coursework');connection(text);
    const recent=[...entries.values()].filter(e=>e.id.startsWith('session:')&&all.some(x=>x.reading.id===e.data.readingId&&readingState(x.reading).progress!=='done')).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];
    const active=recent?all.find(x=>x.reading.id===recent.data.readingId):all.find(x=>readingState(x.reading).progress==='in-progress');
    if(active){const panel=el('section',null,'continue-panel');panel.append(el('p','PICK UP WHERE YOU LEFT OFF','eyebrow'),el('h2',active.reading.title),el('p',recent?.data.resume||readingState(active.reading).resume||`${active.course.name} · Week ${active.week.number}`),a('Continue studying',studyRoute(active.reading),'primary-action'));text.append(panel);}
    const grid=el('div',null,'course-grid');for(const c of data.courses){const plan=entries.get('plan:'+c.id),current=plan?c.weeks[plan.data.week-1]:null;const panel=el('section',null,'course-panel');panel.append(el('p',c.code,'eyebrow'),el('h2',c.name));if(current){const counts=count(c,current);panel.append(el('h3',`Week ${current.number} · ${current.title}`),el('p',`${counts.done} of ${counts.total} reading items checked off`,'progress-summary'));const bar=el('progress');bar.max=counts.total;bar.value=counts.done;bar.setAttribute('aria-label',`${c.name} Week ${current.number} completion`);panel.append(bar,a('Open this week',route(c,current),'primary-action'));panel.append(el('p',`Teaching week set by you on ${new Date(plan.updatedAt).toLocaleDateString()}. Update it when your course moves on.`,'edition-note'));}else panel.append(el('p',ready?'Choose the teaching week you’re in. Course dates haven’t been verified, so no week is assumed.':'Your teaching week and progress will appear when saved coursework loads.','edition-note'));
    const details=el('details',null,'plan-settings');details.open=!current;details.append(el('summary','Set teaching week'),planForm(c));panel.append(details);
    const browse=el('details',null,'browse-weeks');browse.append(el('summary','Browse all weeks'));for(const w of c.weeks){const co=count(c,w);const link=a(`Week ${w.number} · ${w.title}`,route(c,w));if(ready)link.append(el('small',`${co.done}/${co.total} done`));browse.append(link);}panel.append(browse);grid.append(panel);}text.append(grid,a(`Still needed: ${missing.length} readings`,'#needed','gaps-link'));
  }
  function weekView(course,week,text){const counts=count(course,week);setHeading('Week '+week.number,week.title,course.name+' · Coursework');text.append(a('← Coursework','#coursework','week-return'));connection(text);const nav=el('nav',null,'week-picker');nav.setAttribute('aria-label',`${course.name} weeks`);course.weeks.forEach(w=>{const link=a(String(w.number),route(course,w));link.setAttribute('aria-label','Week '+w.number);if(w.number===week.number)link.setAttribute('aria-current','page');nav.append(link);});text.append(nav);if(ready)text.append(el('p',`${counts.done} of ${counts.total} reading items checked off`,'progress-summary'));const unavailable=week.readings.filter(r=>r.status==='missing').length;if(unavailable)text.append(el('p',`${unavailable} reading still needed. The case study is available.`,'week-summary has-gap'));for(const r of week.readings)text.append(card({course,week,reading:r}));
    text.append(fieldsForm(`week:${course.id}:${week.number}`,{notes:''},[{key:'notes',title:'Connections, lecture notes and questions for this week'}],'Week notes'));
    const noteList=el('details',null,'week-note-rollup');noteList.append(el('summary','Notes from this week’s readings'));let hasNotes=false;for(const r of week.readings){const notes=readingState(r).notes;if(notes){hasNotes=true;noteList.append(a(r.title,studyRoute(r)),el('p',notes));}}if(!hasNotes)noteList.append(el('p',ready?'Notes saved on a reading will appear here.':'Load saved coursework to see reading notes.'));text.append(noteList);
    const sources=el('details',null,'week-sources');sources.append(el('summary','Preparation, files & official assignment'));const links=el('div',null,'reading-actions');if(week.preparation)links.append(a('Saved tutorial preparation',week.preparation));links.append(a('Official weekly assignment',week.source),a('Week folder in Drive',week.folder));if(week.tutorial)links.append(a('Tutorial in Canvas',week.tutorial));sources.append(links,el('p',`Reading list checked ${data.checked}. Lectures and videos remain in Canvas. Availability is the last verified collection state.`,'edition-note'));text.append(sources);
  }
  function briefFor({course,week,reading:r}){const s=readingState(r);const recent=[...entries.values()].filter(e=>e.id.startsWith('session:')&&e.data.readingId===r.id).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];return `Be my philosophy study partner. Explain directly when I ask; don't force me to answer first. Quiz me only when I request it.\n\nCourse: ${course.name} (${course.code})\nWeek ${week.number}: ${week.title}\nReading: ${r.author} — ${r.title}\nAssigned scope: ${r.scope}\nEdition: ${states[r.status]}. ${r.note}\nReading file: ${r.url||'Not collected'}\nOther assigned work this week:\n${week.readings.filter(x=>x.id!==r.id).map(x=>'- '+x.author+' — '+x.title+' ('+x.scope+')').join('\n')}\n\nUse the attached reading, or retrieve it through my connected Drive if available. A link alone is not the text: tell me if you cannot access it and ask me to attach it before giving source-specific claims. Distinguish the author's arguments from your interpretation. Cite sections or actual source pages; don't invent anthology page matches.\n\nMy saved notes:\n${s.notes||'(none yet)'}\nWhere to resume:\n${recent?.data.resume||s.resume||'(start with an overview of the central question and argument)'}\n\nAt the end, offer a short session record: what we covered, unresolved questions, and where to resume. Do not mark the reading complete for me.`;}
  function sessionView(context,text){const {course,week,reading:r}=context;setHeading(r.title,`${course.name} · Week ${week.number} · ${r.author||r.kind}`,'Coursework · Study session');text.append(a('← Back to Week '+week.number,route(course,week),'week-return'));connection(text);
    if(!r.url){text.append(el('p','The required text has not been collected yet.','has-gap'));return;}
    const tabnav=el('div',null,'session-tabs');tabnav.setAttribute('role','tablist');tabnav.setAttribute('aria-label','Study workspace');const layout=el('div',null,'session-layout');const panels={};const buttons={};
    for(const name of ['Study','Reading','Notes']){const panel=el('section',null,`session-panel panel-${name.toLowerCase()}`);panel.id='panel-'+name;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab-'+name);const btn=button(name,()=>activate(name));btn.id='tab-'+name;btn.setAttribute('role','tab');btn.setAttribute('aria-controls',panel.id);buttons[name]=btn;panels[name]=panel;tabnav.append(btn);layout.append(panel);}
    function activate(name){for(const key of Object.keys(panels)){panels[key].hidden=key!==name;buttons[key].setAttribute('aria-selected',String(key===name));buttons[key].tabIndex=key===name?0:-1;}}
    tabnav.addEventListener('keydown',e=>{const keys=['Study','Reading','Notes'];let index=keys.findIndex(k=>buttons[k]===document.activeElement);if(index<0)return;if(e.key==='ArrowRight')index=(index+1)%3;else if(e.key==='ArrowLeft')index=(index+2)%3;else if(e.key==='Home')index=0;else if(e.key==='End')index=2;else return;e.preventDefault();activate(keys[index]);buttons[keys[index]].focus();});activate('Study');text.append(tabnav,layout);
    const study=panels.Study,s=readingState(r);study.append(el('h2',s.chatUrl?'Continue your session':'Start a study session'));if(s.chatUrl)study.append(a('Continue in ChatGPT',s.chatUrl,'primary-action'));study.append(a('Open reading',r.url));
    const latestSession=[...entries.values()].filter(e=>e.id.startsWith('session:')&&e.data.readingId===r.id).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];const resume=latestSession?.data.resume||entries.get('reading:'+r.id)?.data.resume;if(resume)study.append(el('p','Where you left off','eyebrow'),el('p',resume,'resume-note'));
    const setup=el('details',null,'session-setup');setup.open=!s.chatUrl;setup.append(el('summary',s.chatUrl?'New conversation / study brief':'Set up this reading in ChatGPT'));const steps=el('ol',null,'study-steps');const step1=el('li','Add this reading to your ChatGPT conversation or project. ');step1.append(a('Open the reading file',r.url));const step2=el('li','Copy the study brief below into that conversation. It includes the assignment, edition notes and your saved notes.');steps.append(step1,step2);setup.append(steps);
    const actions=el('div',null,'reading-actions');const clipboardStatus=el('p',null,'save-status');clipboardStatus.setAttribute('role','status');const brief=el('textarea');brief.readOnly=true;brief.value=briefFor(context);brief.rows=9;brief.setAttribute('aria-label','Study brief to copy into ChatGPT');const briefDetails=el('details',null,'brief-details');briefDetails.append(el('summary','View study brief'),brief);
    actions.append(button('Copy study brief',async()=>{brief.value=briefFor(context);try{await navigator.clipboard.writeText(brief.value);clipboardStatus.textContent='Copied. Paste this in ChatGPT alongside the reading.';}catch{briefDetails.open=true;brief.focus();brief.select();clipboardStatus.textContent='Select and copy the brief below.';}},'primary-action'));
    const chatUrl=s.chatUrl||'https://chatgpt.com/';actions.append(a(s.chatUrl?'Continue conversation in ChatGPT':'Open ChatGPT',chatUrl));setup.append(actions,clipboardStatus,briefDetails,el('p','Attach the reading in ChatGPT, then save the conversation link below to return directly next time.','edition-note'));setup.append(fieldsForm('reading:'+r.id,defaults(),[{key:'chatUrl',title:'Conversation link',input:true,max:2000,placeholder:'https://chatgpt.com/c/…'}]));setup.querySelector('form').onSaved=()=>refresh();study.append(setup);
    const start=button(s.progress==='not-started'?'Mark as in progress':'In progress saved',async()=>{start.disabled=true;try{const id='reading:'+r.id;const record=await save(id,{...readingState(r),progress:'in-progress'},entries.get(id)?.version||0);const d=drafts.get(id);if(d){d.version=record.version;d.data.progress='in-progress';}refresh();}catch(e){clipboardStatus.textContent=e.message;start.disabled=false;}});if(s.progress==='not-started'){start.disabled=!ready;study.append(start);}
    if(!sessionDraftIds.has(r.id))sessionDraftIds.set(r.id,'session:'+crypto.randomUUID());const sessionId=sessionDraftIds.get(r.id);const endDetails=el('details',null,'finish-session');endDetails.append(el('summary','Finish this session'));const finish=draft(sessionId,{readingId:r.id,summary:'',questions:'',resume:''});
    const form=fieldsForm(sessionId,finish.data,[{key:'summary',title:'What we covered',max:8000,rows:3},{key:'questions',title:'Questions still open',max:8000,rows:3},{key:'resume',title:'Where to resume next time',max:8000,rows:2}],'Save a session record');form.onSaved=record=>{sessionDraftIds.delete(r.id);drafts.delete(record.id);persistDrafts();refresh();};const submit=form.querySelector('button[type="submit"]');submit.textContent='Save session record';endDetails.append(form,el('p','This saves your session record. Use the progress control below when you decide the reading is done.','edition-note'));study.append(endDetails);
    const history=[...entries.values()].filter(e=>e.id.startsWith('session:')&&e.data.readingId===r.id).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));if(history.length){const details=el('details',null,'session-history');details.append(el('summary',`Previous sessions (${history.length})`));for(const h of history){const item=el('section');item.append(el('h3',new Date(h.updatedAt).toLocaleString()));for(const [key,name]of [['summary','Covered'],['questions','Open questions'],['resume','Resume here']])if(h.data[key])item.append(el('h4',name),el('p',h.data[key]));details.append(item);}study.append(details);}
    progressControl(r,study);
    const reading=panels.Reading;reading.append(el('p',r.scope),el('p',r.note||states[r.status],'edition-note'),a('Open complete saved file',r.url,'primary-action'));
    if(r.route&&window.HUME_BOOK){const startPart=Number(r.route.split('-').pop());for(let part=startPart;part<startPart+3;part++){const section=window.HUME_BOOK.sections['hume-'+part];const details=el('details',null,'inline-reading');details.open=part===startPart;details.append(el('summary',section.title));const body=el('div',null,'primary-text');for(const paragraph of section.text.split(/\n\s*\n/).filter(Boolean))body.append(el('p',paragraph));details.append(body);reading.append(details);}}else reading.append(el('p','This text opens in Drive. Return here for the study brief, notes and session record.','edition-note'));
    const notes=panels.Notes;notes.append(fieldsForm('reading:'+r.id,defaults(),[{key:'notes',title:'Your notes',placeholder:'Save explanations, arguments, passages and connections.'},{key:'resume',title:'Bookmark / where to resume',rows:2,max:4000},{key:'chatUrl',title:'ChatGPT conversation or project link',input:true,max:2000,placeholder:'https://chatgpt.com/c/…'}],'Reading notes'));notes.append(el('p','Saved reading notes also appear in the week overview. The ChatGPT link is a private conversation or project URL, not a public sharing link.','edition-note'));
  }
  function needed(text){setHeading('Still needed',`${missing.length} required readings not collected · Checked ${data.checked}`,'Coursework · Missing materials');text.append(a('← Coursework','#coursework'));for(const item of missing){const section=el('section',null,'gap-group');section.append(a(`${item.course.name} · Week ${item.week.number}`,route(item.course,item.week),'week-return'),card(item));text.append(section);}const checks=el('section',null,'reference-checks');checks.append(el('h2','Available, with reference questions'));for(const x of all.filter(x=>x.reading.check))checks.append(a(`${x.course.name} · Week ${x.week.number} · ${x.reading.author}`,route(x.course,x.week)));text.append(checks);}
  function setHeading(title,note,context){document.getElementById('section-title').textContent=title;document.getElementById('section-note').textContent=note;document.getElementById('context').textContent=context;}
  function render(key){const match=key.match(/^study-(enlightenment|moral)-([1-8])$/);const session=key.startsWith('session-')?all.find(x=>x.reading.id===key.slice(8)):null;if(key!=='coursework'&&key!=='needed'&&!match&&!session)return false;const text=document.getElementById('text');document.getElementById('reading').classList.add('study-surface');document.getElementById('book-label').textContent='COURSEWORK';document.getElementById('hume-download').hidden=true;if(key==='coursework')home(text);else if(key==='needed')needed(text);else if(session)sessionView(session,text);else{const c=data.courses.find(c=>c.id===match[1]);weekView(c,c.weeks[Number(match[2])-1],text);}return true;}
  const nav=document.getElementById('study-nav');nav.append(a('Coursework','#coursework','reading-link'),a('Still needed · '+missing.length,'#needed','reading-link needs-link'));for(const c of data.courses){const group=el('details',null,'course-group');group.append(el('summary',c.name));for(const w of c.weeks)group.append(a('Week '+w.number,route(c,w),'reading-link week-link'));nav.append(group);}
  window.addEventListener('beforeunload',event=>{if(unsaved()){event.preventDefault();event.returnValue='';}});
  window.STUDY={render,ready:()=>ready,briefFor,isReading:id=>all.some(x=>x.reading.id===id)};load();
})();
